// === Tab: mySketch ===
var nmobiles = 4000;
var mobiles = [];
var noisescale;
var a1, a2, a3, a4, a5, amax;

function setup() {
  createCanvas(800, 800);
  // 1) RGB 模式下用 hex 或 RGB 值指定背景
  colorMode(RGB, 255);
  background('#F6F5F1');
  noFill();
  strokeWeight(0.1);
  reset();
}

function reset() {
  noisescale = random(0.08, 0.1);
  noiseDetail(int(random(1, 5)));
  amax = random(5);
  a1 = random(1, amax);
  a2 = random(1, amax);
  a3 = random(1, amax);
  a4 = random(1, amax);
  a5 = 10;
  for (var i = 0; i < nmobiles; i++) {
    mobiles[i] = new Mobile(i);
  }
}

function draw() {
  for (var i = 0; i < nmobiles; i++) {
    mobiles[i].run();
  }
}

function keyReleased() {
  if (key == 's' || key == 'S') {
    saveCanvas('noise_art_' + day() + month() + hour() + minute() + second() + '.png');
  }
  if (keyCode == 32) reset();
  if (key == 'r' || key == 'R') setup();
}

// “移动体”构造函数
function Mobile(index) {
  this.index = index;
  this.position = createVector(random(width), random(height));
  this.position0 = this.position.copy();
  this.trans = random(50, 100);
}

Mobile.prototype.run = function() {
  this.update();
  this.display();
};

Mobile.prototype.update = function() {
  // 用噪声控制速度方向
  this.velocity = createVector(
    1 - 2 * noise(a4 + a2 * sin(TAU * this.position.x / width),
                  a4 + a2 * sin(TAU * this.position.y / height)),
    1 - 2 * noise(a2 + a3 * cos(TAU * this.position.x / width),
                  a4 + a3 * cos(TAU * this.position.y / height))
  ).mult(a5);

  this.position0 = this.position.copy();
  this.position.add(this.velocity);

  // 出界重置
  if (this.position.x < 0 || this.position.x > width ||
      this.position.y < 0 || this.position.y > height) {
    this.position = createVector(random(width), random(height));
    this.position0 = this.position.copy();
  }
};

Mobile.prototype.display = function() {
  // 2) 用黑色线条（alpha 保留透明度效果）
  stroke(0, this.trans);
  line(this.position0.x, this.position0.y, this.position.x, this.position.y);
};

